import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, "books.json");
const PORT = process.env.PORT || 3000;

function loadBooks() {
  try {
    if (!fs.existsSync(DATA_FILE)) {
      fs.writeFileSync(DATA_FILE, "[]", "utf8");
      return [];
    }
    const raw = fs.readFileSync(DATA_FILE, "utf8");
    if (!raw.trim()) return [];
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

function saveBooks(books) {
  fs.writeFileSync(DATA_FILE, JSON.stringify(books, null, 2), "utf8");
}

function parseBody(req) {
  return new Promise((resolve) => {
    let body = "";
    req.on("data", (chunk) => (body += chunk));
    req.on("end", () => {
      const ct = req.headers["content-type"] || "";
      if (ct.includes("application/json")) {
        try {
          resolve(JSON.parse(body));
        } catch {
          resolve({});
        }
      } else if (ct.includes("application/x-www-form-urlencoded")) {
        const params = new URLSearchParams(body);
        const obj = {};
        for (const [k, v] of params) obj[k] = v;
        resolve(obj);
      } else {
        if (body.startsWith("{")) {
          try {
            resolve(JSON.parse(body));
            return;
          } catch {}
        }
        const params = new URLSearchParams(body);
        if ([...params].length > 0) {
          const obj = {};
          for (const [k, v] of params) obj[k] = v;
          resolve(obj);
          return;
        }
        resolve({});
      }
    });
  });
}

function escapeHtml(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
*{box-sizing:border-box;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
body{max-width:800px;margin:2rem auto;padding:0 1rem;color:#222;background:#fff}
h1 a{color:inherit;text-decoration:none}
section{margin:2rem 0}
.book{border:1px solid #ddd;border-radius:8px;padding:1rem;margin:.5rem 0;display:flex;justify-content:space-between;align-items:center}
.book a{font-weight:600;color:#0b57d0;text-decoration:none}
.book a:hover{text-decoration:underline}
.status{font-size:.8rem;padding:.2rem .5rem;border-radius:999px;background:#eef0f3}
.status.finished{background:#d4edda}
form.add{border:1px solid #ddd;border-radius:8px;padding:1rem;background:#fafafa}
form.add label{display:block;margin:.5rem 0 .2rem;font-weight:600}
form.add input,form.add textarea{width:100%;padding:.5rem;border:1px solid #ccc;border-radius:6px}
form.add button{margin-top:1rem;padding:.6rem 1rem;background:#0b57d0;color:#fff;border:0;border-radius:6px;cursor:pointer}
form.add button:hover{background:#0946a8}
.inline-form{display:inline}
.inline-form button{padding:.4rem .8rem;background:#198754;color:#fff;border:0;border-radius:6px;cursor:pointer}
.inline-form button:hover{background:#157347}
.detail{border:1px solid #ddd;border-radius:8px;padding:1.5rem}
.detail h2{margin-top:0}
.share{margin-top:1rem;font-size:.9rem;color:#555}
.share input{width:100%;padding:.5rem;border:1px solid #ccc;border-radius:6px;background:#f8f9fa}
a.back{display:inline-block;margin-bottom:1rem;color:#0b57d0;text-decoration:none}
</style>
</head>
<body>
<h1><a href="/">My Books</a></h1>
${body}
</body>
</html>`;
}

function homePage(books) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books.filter((b) => b.status === "finished");

  const renderList = (list) =>
    list.length === 0
      ? `<p>No books yet.</p>`
      : list
          .map(
            (b) => `
        <div class="book">
          <div>
            <a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>
            <span> by ${escapeHtml(b.author)}</span>
          </div>
          <div style="display:flex;gap:.5rem;align-items:center">
            <span class="status ${b.status === "finished" ? "finished" : ""}">${escapeHtml(b.status === "finished" ? "Finished" : "Reading")}</span>
            ${
              b.status !== "finished"
                ? `<form class="inline-form" method="POST" action="/books/${escapeHtml(b.id)}/finish">
                    <button type="submit">Mark as finished</button>
                   </form>`
                : ""
            }
          </div>
        </div>`
          )
          .join("");

  return layout(
    "My Books",
    `
  <form class="add" method="POST" action="/books">
    <h2>Add a book</h2>
    <label for="title">Title</label>
    <input id="title" name="title" required placeholder="Book title">
    <label for="author">Author</label>
    <input id="author" name="author" required placeholder="Author name">
    <label for="notes">Notes</label>
    <textarea id="notes" name="notes" rows="3" placeholder="Your notes..."></textarea>
    <button type="submit">Add book</button>
  </form>

  <section>
    <h2>Currently Reading</h2>
    ${renderList(reading)}
  </section>

  <section>
    <h2>Finished</h2>
    ${renderList(finished)}
  </section>
`
  );
}

function detailPage(book, req) {
  const host = req.headers.host || `localhost:${PORT}`;
  const protocol = req.headers["x-forwarded-proto"] || "http";
  const shareUrl = `${protocol}://${host}/books/${book.id}`;

  return layout(
    book.title,
    `
  <a class="back" href="/">← Back to all books</a>
  <div class="detail">
    <h2>${escapeHtml(book.title)}</h2>
    <p><strong>Author:</strong> ${escapeHtml(book.author)}</p>
    <p><strong>Status:</strong> ${escapeHtml(book.status)}</p>
    <p><strong>Notes:</strong> ${escapeHtml(book.notes || "No notes")}</p>
    ${
      book.status !== "finished"
        ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish">
            <button type="submit" style="padding:.5rem 1rem;background:#198754;color:#fff;border:0;border-radius:6px;cursor:pointer">Mark as finished</button>
           </form>`
        : ""
    }
    <div class="share">
      <p><strong>Share this book:</strong> send someone this link</p>
      <input type="text" value="${escapeHtml(shareUrl)}" readonly onclick="this.select()">
    </div>
  </div>
`
  );
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || "localhost"}`);
  const pathname = url.pathname;
  const method = req.method;

  if (method === "GET" && pathname === "/") {
    const books = loadBooks();
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(homePage(books));
    return;
  }

  if (method === "GET" && pathname.startsWith("/books/")) {
    const id = decodeURIComponent(pathname.slice("/books/".length).split("/")[0]);
    if (!id) {
      res.writeHead(404, { "Content-Type": "text/html" });
      res.end(layout("Not found", "<h2>Book not found</h2><a href='/'>Back</a>"));
      return;
    }
    const books = loadBooks();
    const book = books.find((b) => b.id === id);
    if (!book) {
      res.writeHead(404, { "Content-Type": "text/html" });
      res.end(layout("Not found", "<h2>Book not found</h2><a class='back' href='/'>← Back</a>"));
      return;
    }
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(detailPage(book, req));
    return;
  }

  if ((method === "GET" || method === "HEAD") && pathname === "/books.json") {
    const books = loadBooks();
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(books));
    return;
  }

  if (method === "GET" && pathname === "/api/books") {
    const books = loadBooks();
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(books));
    return;
  }

  if (pathname === "/books" && method === "POST") {
    const body = await parseBody(req);
    const title = (body.title || "").trim();
    const author = (body.author || "").trim();
    const notes = (body.notes || "").trim();

    if (!title || !author) {
      res.writeHead(400, { "Content-Type": "text/html" });
      res.end(layout("Error", "<p>Title and author are required.</p><a href='/'>Back</a>"));
      return;
    }

    const books = loadBooks();
    const newBook = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: "reading",
      createdAt: new Date().toISOString(),
    };
    books.push(newBook);
    saveBooks(books);

    const accept = req.headers.accept || "";
    if (accept.includes("application/json") || (req.headers["content-type"] || "").includes("application/json")) {
      res.writeHead(201, { "Content-Type": "application/json" });
      res.end(JSON.stringify(newBook));
      return;
    }

    res.writeHead(302, { Location: "/" });
    res.end();
    return;
  }

  if (pathname === "/add" && method === "POST") {
    const body = await parseBody(req);
    const title = (body.title || "").trim();
    const author = (body.author || "").trim();
    const notes = (body.notes || "").trim();
    if (!title || !author) {
      res.writeHead(400, { "Content-Type": "text/html" });
      res.end(layout("Error", "<p>Title and author required</p>"));
      return;
    }
    const books = loadBooks();
    const newBook = { id: randomUUID(), title, author, notes, status: "reading", createdAt: new Date().toISOString() };
    books.push(newBook);
    saveBooks(books);
    res.writeHead(302, { Location: "/" });
    res.end();
    return;
  }

  const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish\/?$/);
  if (finishMatch && (method === "POST" || method === "PUT" || method === "PATCH")) {
    const id = decodeURIComponent(finishMatch[1]);
    const books = loadBooks();
    const idx = books.findIndex((b) => b.id === id);
    if (idx === -1) {
      res.writeHead(404, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Not found" }));
      return;
    }
    books[idx].status = "finished";
    saveBooks(books);

    const ct = req.headers["content-type"] || "";
    const accept = req.headers.accept || "";
    if (ct.includes("application/json") || accept.includes("application/json")) {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify(books[idx]));
      return;
    }

    const referer = req.headers.referer || "/";
    if (pathname.startsWith("/books/") && req.headers.referer && req.headers.referer.includes("/books/")) {
      res.writeHead(302, { Location: `/books/${id}` });
    } else {
      res.writeHead(302, { Location: "/" });
    }
    res.end();
    return;
  }

  const apiFinishMatch = pathname.match(/^\/api\/books\/([^/]+)\/finish\/?$/);
  if (apiFinishMatch && (method === "POST" || method === "PUT" || method === "PATCH")) {
    const id = decodeURIComponent(apiFinishMatch[1]);
    const books = loadBooks();
    const idx = books.findIndex((b) => b.id === id);
    if (idx === -1) {
      res.writeHead(404, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Not found" }));
      return;
    }
    books[idx].status = "finished";
    saveBooks(books);
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(books[idx]));
    return;
  }

  if (method === "GET" && pathname === "/health") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ ok: true }));
    return;
  }

  res.writeHead(404, { "Content-Type": "text/html" });
  res.end(layout("Not found", "<h2>Page not found</h2><a href='/'>Go home</a>"));
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

export { server, loadBooks, saveBooks, DATA_FILE };

