function homePage(books) {
  const reading = books.filter((b) => b.status !== "finished");
  const finished = books.filter((b) => b.status === "finished");

  const renderList = (list) =>
    list.length === 0
      ? `<p>No books yet.</p>`
      : list
          .map(
            (b) => `
        <div class="book">
          <div>
            <a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a>
            <span> by ${escapeHtml(b.author)}</span>
          </div>
          <div style="display:flex;gap:.5rem;align-items:center">
            <span class="status ${b.status === "finished" ? "finished" : ""}">${escapeHtml(b.status === "finished" ? "Finished" : "Reading")}</span>
            ${
              b.status !== "finished"
                ? `<form class="inline-form" method="POST" action="/books/${escapeHtml(b.id)}/finish">
                    <button type="submit">Mark as finished</button>
                   </form>`
                : ""
            }
          </div>
        </div>`
          )
          .join("");

  return layout(
    "My Books",
    `
  <form class="add" method="POST" action="/books">
    <h2>Add a book</h2>
    <label for="title">Title</label>
    <input id="title" name="title" required placeholder="Book title">
    <label for="author">Author</label>
    <input id="author" name="author" required placeholder="Author name">
    <label for="notes">Notes</label>
    <textarea id="notes" name="notes" rows="3" placeholder="Your notes..."></textarea>
    <button type="submit">Add book</button>
  </form>

  <section>
    <h2>Currently Reading</h2>
    ${renderList(reading)}
  </section>

  <section>
    <h2>Finished</h2>
    ${renderList(finished)}
  </section>
`
  );
}

function detailPage(book, req) {
  const host = req.headers.host || `localhost:${PORT}`;
  const protocol = req.headers["x-forwarded-proto"] || "http";
  const shareUrl = `${protocol}://${host}/books/${book.id}`;

  return layout(
    book.title,
    `
  <a class="back" href="/">← Back to all books</a>
  <div class="detail">
    <h2>${escapeHtml(book.title)}</h2>
